--
-- Table structure for table `daily_special_scores`
--

DROP TABLE IF EXISTS `daily_special_scores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_special_scores` (
  `rank_date` date NOT NULL,
  `player_id` varchar(191) NOT NULL,
  `level` int(10) unsigned NOT NULL,
  `score` bigint(20) unsigned NOT NULL DEFAULT 0,
  `combo` int(10) unsigned NOT NULL DEFAULT 0,
  `special_score` bigint(20) unsigned NOT NULL DEFAULT 0,
  `time_ms` bigint(20) unsigned NOT NULL DEFAULT 0,
  `display_name` varchar(191) DEFAULT NULL,
  `avatar_url` varchar(512) DEFAULT NULL,
  `external_id` varchar(64) NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`rank_date`,`player_id`),
  KEY `idx_daily_special_rank` (`rank_date`,`special_score`,`time_ms`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

