DROP TABLE IF EXISTS `game_difficulty_ranges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_difficulty_ranges` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `mode` varchar(32) NOT NULL DEFAULT 'normal',
  `start_level` int(10) unsigned NOT NULL,
  `end_level` int(10) unsigned NOT NULL,
  `difficulty` tinyint(3) unsigned NOT NULL,
  `grid_w` smallint(5) unsigned NOT NULL,
  `grid_h` smallint(5) unsigned NOT NULL,
  `max_layers` smallint(5) unsigned NOT NULL,
  `min_tiles` smallint(5) unsigned NOT NULL,
  `max_tiles` smallint(5) unsigned NOT NULL,
  `chaos` decimal(5,4) NOT NULL,
  `min_available_pairs` smallint(5) unsigned NOT NULL,
  `hidden_ratio` decimal(5,4) NOT NULL,
  `special_pair_count` smallint(5) unsigned NOT NULL,
  `curve_type` varchar(16) NOT NULL DEFAULT 'wave',
  `curve_amplitude` decimal(6,4) NOT NULL DEFAULT 0.1000,
  `curve_cycles` decimal(6,2) NOT NULL DEFAULT 1.00,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_difficulty_range` (`mode`,`start_level`,`end_level`)
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
