DROP TABLE IF EXISTS `player_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `player_profiles` (
  `player_id` varchar(191) NOT NULL,
  `name` varchar(191) DEFAULT NULL,
  `avatar_id` int(10) unsigned NOT NULL DEFAULT 0,
  `avatar_frame_id` int(10) unsigned NOT NULL DEFAULT 0,
  `perfect_combo_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `extra_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`extra_data`)),
  `registration_time` datetime(3) DEFAULT NULL,
  `last_login_time` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`player_id`),
  KEY `idx_player_profiles_name` (`name`),
  KEY `idx_player_profiles_updated` (`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

